import sys
from typing import List, Tuple

def cross_product(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> int:
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def is_left_turn(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    return cross_product(o, a, b) > 0

def is_right_turn(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    return cross_product(o, b, a) > 0

def is_non_self_intersecting(points: List[Tuple[int, int]]) -> bool:
    n = len(points)
    for i in range(n):
        for j in range(i + 2, n - 1):
            if (cross_product(points[i], points[i + 1], points[j]) *
                cross_product(points[i], points[i + 1], points[j + 1]) > 0):
                return False
    return True

def find_permutation(n: int, points: List[Tuple[int, int]], s: str) -> List[int]:
    if n == 3:
        if s == "L":
            return [1, 2, 3]
        elif s == "R":
            return [1, 3, 2]
        else:
            return [-1]

    # Sort points by x-coordinate, and by y-coordinate if x-coordinates are equal
    points = sorted(enumerate(points), key=lambda x: (x[1][0], x[1][1]))
    indices = [p[0] + 1 for p in points]

    # Check if the sorted order satisfies the winding condition
    turns = []
    for i in range(n - 2):
        if is_left_turn(points[i][1], points[i + 1][1], points[i + 2][1]):
            turns.append("L")
        elif is_right_turn(points[i][1], points[i + 1][1], points[i + 2][1]):
            turns.append("R")
        else:
            return [-1]

    if "".join(turns) == s:
        return indices

    # Try to find a valid permutation by rotating the sorted order
    for k in range(1, n):
        rotated_indices = indices[k:] + indices[:k]
        rotated_points = [(rotated_indices[i] - 1, points[i][1]) for i in range(n)]
        turns = []
        for i in range(n - 2):
            if is_left_turn(rotated_points[i][1], rotated_points[i + 1][1], rotated_points[i + 2][1]):
                turns.append("L")
            elif is_right_turn(rotated_points[i][1], rotated_points[i + 1][1], rotated_points[i + 2][1]):
                turns.append("R")
            else:
                break
        else:
            if "".join(turns) == s and is_non_self_intersecting([points[i][1] for i in rotated_indices]):
                return rotated_indices

    return [-1]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    points = []
    index = 1
    for _ in range(n):
        x = int(data[index])
        y = int(data[index + 1])
        points.append((x, y))
        index += 2

    s = data[-1]

    result = find_permutation(n, points, s)
    if result == [-1]:
        print(-1)
    else:
        print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
